// Build the live value object and the immutable defaults from the schema.
const DEFAULTS = {};
for (const cat of TUNING_SCHEMA) for (const p of cat.params) DEFAULTS[p.key] = p.def;

// Live, mutable values the sim reads. Starts at defaults (== old constants).
export const T = { ...DEFAULTS };

// Amortised-cadence check usable INSIDE a phase-offset pass. index.js fires the
// heavy passes at distinct phase offsets (`_at(base, phase)` — step ≡ phase mod
// interval), which makes any naive `world.step % EVERY === 0` inside such a
// pass DEAD: the pass's residue never lands on 0 mod EVERY (this silently froze
// the alliance map at its first build, and left prunePersons unreachable).
// Instead, fire on the FIRST firing of the given pass inside each EVERY-wide
// window: a pure function of the step — no new state, so determinism and
// save/load continuation are untouched — firing exactly once per window at any
// granularity or phase. `passBase` is the calling pass's own base interval
// (e.g. T.POLITY_INTERVAL, DYNASTY_INTERVAL); the Math.max clamp covers a
// window narrower than the pass interval (then every pass qualifies).
export function passWindow(world, passBase, every) {
  const G = T.SIM_GRANULARITY || 1;
  const ivl = Math.max(1, Math.round(passBase * G));
  return world.step % Math.max(ivl, Math.round(every * G)) < ivl;
}

// ── Resolution-invariant population normalisation (T.RES_INVARIANT_POP) ──
// docs/resolution-invariance-plan.md. The same Earth must hold the same real
// population at any grid resolution, so DISTANCES in the settlement/food path
// scale by rNormPop (constant real distance) and AREA sums/caps by rNormPop²
// (constant real area). world.tw is the SIM TILE grid — half the requested
// pixel width (tileRes 2) — so the reference is the calibrated 480-pixel
// world's 240-TILE grid, the same RES_REF_W countryTerritory.js normalises
// territory reach against. Lever off ⇒ exactly 1 (byte-identical); at the
// reference grid the factor is 1 by construction (the fixed point).
export const POP_REF_W = 240;
export function rNormPop(world) { return T.RES_INVARIANT_POP ? world.tw / POP_REF_W : 1; }

// Monotonic version stamp, bumped on every lever change. Lets per-tick caches
// derived from T (e.g. transport.js edge-cost params) invalidate immediately
// when a slider moves, instead of serving stale numbers for the rest of a tick.
export const TUNING_VERSION = { v: 1 };

// Apply a partial override map (from the Tuning menu / worker message). Only
// known keys are accepted, and only finite numbers — a malformed message can
// never poison the sim.
export function applyTuning(overrides) {
  if (!overrides) return;
  for (const k in overrides) {
    if (!(k in DEFAULTS)) continue;
    const v = Number(overrides[k]);
    if (Number.isFinite(v)) T[k] = v;
  }
  TUNING_VERSION.v++;
}

// Reset every lever to its hand-tuned default.
export function resetTuning() { Object.assign(T, DEFAULTS); TUNING_VERSION.v++; }

// The defaults, for the menu's "reset" affordance / change indicators.
export function tuningDefaults() { return { ...DEFAULTS }; }
